using System;using System.IO;using System.Security.Cryptography;using System.Text;
namespace Synkoz {public sealed partial class Montage {public string WorkspaceR11;}public static class ProjectStorageR11 {public static string Root(Montage m){if(!string.IsNullOrWhiteSpace(m.WorkspaceR11)){Directory.CreateDirectory(m.WorkspaceR11);return m.WorkspaceR11;}string identity=Path.GetFullPath(m.Folder??Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments));string name=Path.GetFileName(identity.TrimEnd(Path.DirectorySeparatorChar));string suffix;using(var h=SHA256.Create())suffix=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(identity.ToUpperInvariant()))).Replace("-","").Substring(0,12);string root=string.IsNullOrEmpty(m.ProjectFile)?Path.Combine(FoldersR2.Get("project"),name+"-"+suffix):Path.Combine(Path.GetDirectoryName(Path.GetFullPath(m.ProjectFile)),Path.GetFileNameWithoutExtension(m.ProjectFile)+".contenu");Directory.CreateDirectory(root);m.WorkspaceR11=root;return root;}public static string Cache(Montage m,string kind){string p=Path.Combine(Root(m),"Cache",kind);Directory.CreateDirectory(p);return p;}public static string Resources(Montage m){string p=Path.Combine(Root(m),"Ressources");Directory.CreateDirectory(p);return p;}}}
